//go:build e2e

package e2e_test

import (
	"net/http"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"go-htmx-template/internal/dist"
)

func TestNavigation_404ForUnknownRoutes(t *testing.T) {
	t.Parallel()
	client := &http.Client{Timeout: 5 * time.Second}

	resp, err := client.Get(getFullPath("/nonexistent"))
	require.NoError(t, err)
	defer resp.Body.Close()

	assert.Equal(t, http.StatusNotFound, resp.StatusCode)
}

// TestNavigation_AssetsAreServed guards the build artifacts the page depends on:
// the CSS is generated by go-tw and is gitignored, so a missing build step
// would otherwise show up only as an unstyled page.
func TestNavigation_AssetsAreServed(t *testing.T) {
	t.Parallel()

	client := &http.Client{Timeout: 5 * time.Second}

	htmxPath, err := dist.AssetPath("js/htmx@*.min.js")
	require.NoError(t, err)

	for _, path := range []string{"/assets/css/output@dev.css", "/assets/" + htmxPath} {
		resp, err := client.Get(getFullPath(path))
		require.NoError(t, err)

		assert.Equal(t, http.StatusOK, resp.StatusCode, "asset %s", path)
		resp.Body.Close()
	}
}
